368.     if ($plugins.ContainsKey($p.Key)) { $installed = $plugins[$p.Key] }
369.     if (-not $installed) { $installed = Get-PluginVersionFromLocalInstall -PluginKey $p.Key }
370.     if (-not $installed) {
371.         Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed "-" -Required $p.Required -Status "FAIL" -Notes "Plugin not installed"
372.         continue
373.     }
374.     $ok = Compare-Version -Actual $installed -Minimum $p.Required
375.     $status = if ($ok -eq $true) { "OK" } else { "WARN" }
376.     $notes = if ($ok -eq $true) { "" } else { "Below recommended baseline" }
377.     Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed $installed -Required $p.Required -Status $status -Notes $notes
378. }
379. 
380. if (Test-Path Env:GITHUB_TOKEN) {
381.     $ghAuth = Get-CommandTextOutput -Name "gh" -CommandArgs @("auth", "status")
382.     if ($ghAuth -and $ghAuth -match 'token in GITHUB_TOKEN is invalid') {
