384.     }
385. }
386. 
387. # Entire repo readiness
388. $entireSettingsPath = Join-Path $PSScriptRoot "..\\.entire\settings.json"
389. $entireEnabled = $false
390. if (Test-Path $entireSettingsPath) {
391.     try {
392.         $entireSettings = Get-Content $entireSettingsPath -Raw | ConvertFrom-Json
393.         $entireEnabled = $entireSettings.enabled -eq $true
394.     } catch { }
395. }
396. $entireEnabledStatus = if ($entireEnabled) { "OK" } else { "FAIL" }
397. $entireEnabledNotes = if ($entireEnabled) { "" } else { "Run: entire enable -y --agent copilot-cli" }
398. $entireEnabledInstalled = if ($entireEnabled) { "true" } else { "-" }
399. Add-Result -List $results -Category "Entire" -Name "repo enabled (.entire/settings.json)" -Installed $entireEnabledInstalled -Required "true" -Status $entireEnabledStatus -Notes $entireEnabledNotes
400. 
401. $hooksDir = Join-Path $PSScriptRoot "..\.git\hooks"
402. if (!(Test-Path $hooksDir)) {
403.     # worktree: .git is a file pointing to .git/worktrees/<name>; hooks are in main .git/hooks
404.     $gitFile = Join-Path $PSScriptRoot "..\.git"
405.     if (Test-Path $gitFile -PathType Leaf) {
406.         $gitFileContent = Get-Content $gitFile -Raw
407.         $m = [regex]::Match($gitFileContent, 'gitdir:\s*(.+)')
408.         if ($m.Success) {
409.             # Traverse up: .git/worktrees/<name> -> .git -> hooks
410.             $worktreeGitDir = $m.Groups[1].Value.Trim()
411.             $mainGitDir = Split-Path (Split-Path $worktreeGitDir -Parent) -Parent
412.             $hooksDir = Join-Path $mainGitDir "hooks"
413.         }
414.     }
415. }
416. $entireHooks = @('commit-msg', 'post-commit', 'pre-push', 'prepare-commit-msg')
417. $installedHooks = @()
418. if (Test-Path $hooksDir) {
419.     $installedHooks = @(Get-ChildItem $hooksDir -Name | Where-Object { $_ -notmatch '\.sample$' })
420. }
421. $hooksOk = (@($entireHooks | Where-Object { $installedHooks -contains $_ })).Count -eq $entireHooks.Count
422. $hooksStatus = if ($hooksOk) { "OK" } else { "FAIL" }
423. $hooksNotes = if ($hooksOk) { "" } else { "Run: entire enable -y --agent copilot-cli" }
424. $hooksInstalled = if ($hooksOk) { "yes" } else { "-" }
425. Add-Result -List $results -Category "Entire" -Name "git hooks installed" -Installed $hooksInstalled -Required "yes" -Status $hooksStatus -Notes $hooksNotes
426. 
427. # Entire skills check
428. $expectedSkills = @('using-entire', 'what-happened', 'search', 'recall', 'replay', 'review', 'explain', 'teach', 'session-handoff', 'session-crosslink', 'session-to-skill', 'address-findings')
429. $skillsRoot = Join-Path $env:USERPROFILE '.copilot\skills'
430. $missingSkills = @($expectedSkills | Where-Object { !(Test-Path (Join-Path $skillsRoot $_)) })
431. $skillsOk = $missingSkills.Count -eq 0
432. $skillsStatus = if ($skillsOk) { "OK" } else { "WARN" }
433. $skillsNotes = if ($skillsOk) { "" } else { "Missing: $($missingSkills -join ', '). Run with -Setup or: npx skills add https://github.com/entireio/skills --all" }
434. $skillsInstalled = if ($skillsOk) { "$($expectedSkills.Count)/$($expectedSkills.Count)" } else { "$($expectedSkills.Count - $missingSkills.Count)/$($expectedSkills.Count)" }
435. Add-Result -List $results -Category "Entire" -Name "skills (~/.copilot/skills)" -Installed $skillsInstalled -Required "$($expectedSkills.Count)/$($expectedSkills.Count)" -Status $skillsStatus -Notes $skillsNotes
436. 
437. if ($Json) {
438.     $results | ConvertTo-Json -Depth 4
439. } else {
440.     Write-Host ""
441.     Write-Host "Tech stack readiness report" -ForegroundColor Cyan
442.     Write-Host "=========================="
443.     $results | Sort-Object Category, Name | Format-Table -AutoSize
444. 
445.     $failCount = @($results | Where-Object { $_.Status -eq "FAIL" }).Count
446.     $warnCount = @($results | Where-Object { $_.Status -eq "WARN" }).Count
447.     Write-Host ""
448.     if ($failCount -eq 0 -and $warnCount -eq 0) {
449.         Write-Host "Result: READY" -ForegroundColor Green
450.     } elseif ($failCount -eq 0) {
451.         Write-Host "Result: READY WITH WARNINGS ($warnCount warning(s))" -ForegroundColor Yellow
452.     } else {
453.         Write-Host "Result: NOT READY ($failCount fail(s), $warnCount warning(s))" -ForegroundColor Red
454.     }
455. }
